            "も ajaib: だれもきません (dare mo kimasen, tidak ada yang datang — dengan negatif jadi tidak sama sekali), いつも (itsumo, selalu), どこも (tidak mana-mana + negatif). Satu も banyak wajah, hafalkan paketnya.",
            "Orang Indonesia と untuk semua dan: わたしとブディです vs わたしもブディ? Eh beda: と dan (sejajar), も juga (tambah). パンとたまごをたべます (makan roti dan telur) vs わたしもたべます (aku juga makan). Pilih sesuai."
